/**
 * One edit, of one kind (the requirement's table):
 * - `moved`: the span from `start` to `end` (each unique in `ref`, both included) left the body for `ref`; `digest` is the
 *   span's sha256 before the move; the body now carries `after`, and the undo puts back `lead + span + trail`. `existing`:
 *   the reference held the span before the move (it shared it with the body), so the undo copies it back and adds
 *   nothing to the reference. `copied`: sentences of the span a second reference also carries (M10's walk order).
 * - `removed`: `before` → `after` by `ruling`; `phrase`, specific to the removed text, occurs nowhere in the generated skill.
 * - `reworded`: `before` → `after`; whether the meaning is kept is the reviewer's judgement.
 * - `restated`: `before` → `after` drops text that restates `steps`, each still in the body.
 * - `shared`: any of these on a constant every body of `bodies` carries; undone in each.
 */
export type CutPair = {
  id: string;
  bodies: string[];
  kind: 'moved' | 'removed' | 'reworded' | 'restated';
  shared?: true;
  ruling?: string;
  ref?: string;
  existing?: true;
  start?: string;
  end?: string;
  digest?: string;
  lead?: string;
  trail?: string;
  before?: string;
  after: string;
  phrase?: string;
  steps?: string[];
  copied?: { ref: string; text: string };
};

